PREFIX brick: <http://brickschema.org/schema/1.1/brick#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX ref: <https://example.com/ref#>
SELECT ?zone ?label WHERE {
  ?zone a brick:HVAC_Zone ;
        rdfs:label ?label .
  FILTER(CONTAINS(?label, "DataCenter_top_ZN_6"))
}

PREFIX brick: <http://brickschema.org/schema/1.1/brick#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?z WHERE {
  ?z a brick:Zone .
} LIMIT 5

PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?z ?label WHERE {
  ?z a brick:HVAC_Zone .
  ?z rdfs:label ?label .
} LIMIT 30

PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX ref: <https://example.com/ref#>
SELECT ?sensor ?class ?tsid WHERE {
  ?sensor a ?class ;
          brick:hasLocation http://buildgraph.org/BG_large_office_2004_0000#Zone_F2_Z09 .
  FILTER(?class IN (brick:Electric_Power_Sensor, brick:Occupancy_Sensor, brick:Lighting_Power_Sensor))
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
SELECT ?class WHERE {
  ?sensor a ?class ;
          brick:hasLocation <http://buildgraph.org/BG_large_office_2004_0000#Zone_F2_Z09> .
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
SELECT ?s ?c WHERE {
  ?s a ?c .
  FILTER(CONTAINS(STR(?c), "Power"))
} LIMIT 20

PREFIX brick: <https://brickschema.org/schema/Brick#>
SELECT ?p ?c WHERE {
  <http://buildgraph.org/BG_large_office_2004_0000#Zone_F2_Z09> brick:hasPoint ?p .
  ?p a ?c .
}

PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
SELECT ?p ?ext WHERE {
  ?p ref:hasExternalReference ?ext .
  FILTER(?p IN (<http://buildgraph.org/BG_large_office_2004_0000#Zone_F2_Z09.Occupancy_Sensor>, <http://buildgraph.org/BG_large_office_2004_0000#Zone_F2_Z09_Electric_Power_Sensor>))
}
